mapper.select:
/* CastApiMapper.retrieveFlightSchedule(CastReqGetResourceDto dto) */
SELECT NVL(F.DomStatus, ' ') AS domStatus , NVL(F.FlightDirection, ' ') AS flightDirection , NVL(F.DepArrTerminal, ' ') AS depArrTerminal , NVL(F.AirlineCode, ' ') AS airlineCode , NVL(F.OperatorCat, ' ') AS operatorCat , NVL(F.FlightNumber, ' ') AS flightNumber , NVL(F.FlightNumberID, ' ') AS flightNumberID , NVL(F.ScheduleTime, ' ') AS scheduleTime , NVL(F.EstimatedTime, ' ') AS estimatedTime , NVL(F.ActualTime, ' ') AS actualTime , NVL(F.AirportCode, ' ') AS airportCode , NVL(TO_CHAR(F.StandNumber), ' ') AS standNumber , NVL(TO_CHAR(F.Gate), ' ') AS gate , NVL(F.ContactRemote, ' ') AS contactRemote , NVL(TO_CHAR(F.Seats), ' ') AS seats , NVL(TO_CHAR(F.PaxCount), ' ') AS paxCount , NVL(TO_CHAR(F.TransferPax), ' ') AS transferPax , NVL(F.Belt, ' ') AS belt , NVL(F.FlightType, ' ') AS flightType , NVL(F.CheckinRange, ' ') AS checkInRange , NVL(F.AircraftType, ' ') AS aircraftType , NVL(F.SBDAvailable, ' ') AS sbdAvailable , NVL(F.Triangle, ' ') AS triangle , NVL(F.BUS, ' ') AS bus , NVL(F.ArrivalGate, ' ') AS arrivalGate , NVL(F.BaggageT1, ' ') AS baggageT1 , NVL(F.BaggageT2, ' ') AS baggageT2 , TO_CHAR(SYSDATE, 'YYYY-MM-DD"T"HH24:MI:SS') AS lastModified FROM () F ORDER BY F.DomStatus, F.FlightDirection, F.DepArrTerminal, F.FlightNumber, F.FlightNumberID
SELECT NVL(X.domStatus, ' ') AS domStatus , NVL(X.flightDirection, ' ') AS flightDirection , NVL(X.depArrTerminal, ' ') AS depArrTerminal , NVL(X.airlineCode, ' ') AS airlineCode , NVL(X.operatorCat, ' ') AS operatorCat , NVL(X.flightNumber, ' ') AS flightNumber , NVL(X.flightNumberID, ' ') AS flightNumberID , NVL(X.scheduleTime, ' ') AS scheduleTime , NVL(X.estimatedTime, ' ') AS estimatedTime , NVL(X.actualTime, ' ') AS actualTime , NVL(X.airportCode, ' ') AS airportCode , NVL(TO_CHAR(X.standNumber), ' ') AS standNumber , NVL(TO_CHAR(X.gate), ' ') AS gate , NVL(X.contactRemote, ' ') AS contactRemote , NVL(TO_CHAR(X.seats), ' ') AS seats , NVL(TO_CHAR(X.paxCount), ' ') AS paxCount , NVL(TO_CHAR(X.transferPax), ' ') AS transferPax , NVL(X.belt, ' ') AS belt , NVL(X.flightType, ' ') AS flightType , NVL(X.checkInRange, ' ') AS checkInRange , NVL(X.aircraftType, ' ') AS aircraftType , NVL(X.sbdAvailable, ' ') AS sbdAvailable , NVL(X.triangle, ' ') AS triangle , NVL(X.bus, ' ') AS bus , NVL(X.arrivalGate, ' ') AS arrivalGate , NVL(X.baggageT1, ' ') AS baggageT1 , NVL(X.baggageT2, ' ') AS baggageT2 , TO_CHAR(SYSDATE, 'YYYY-MM-DD"T"HH24:MI:SS') AS lastModified FROM ( SELECT CASE WHEN A.DOM_INTL_SE_CD = 'I' THEN 'Int' WHEN A.DOM_INTL_SE_CD = 'D' THEN 'Dom' ELSE '' END AS domStatus , A.ARR_DEP_SE_CD AS flightDirection , A.TMNL_ID AS depArrTerminal , A.ALN_CD AS airlineCode , A.ALN_CTGRY AS operatorCat , A.FLTNM AS flightNumber , A.FLTNM || '_' || TO_CHAR(TO_DATE(A.DEP_ARR_YMD, 'YYYY-MM-DD'), 'YYYY-MM-DD') || 'T' || TO_CHAR(TO_DATE(A.DEP_ARR_HM || '00', 'HH24:MI:SS'), 'HH24:MI:SS') || '.000' AS flightNumberID , TO_CHAR(TO_DATE(A.DEP_ARR_YMD, 'YYYY-MM-DD'), 'YYYY-MM-DD') || 'T' || TO_CHAR(TO_DATE(A.DEP_ARR_HM || '00', 'HH24:MI:SS'), 'HH24:MI:SS') || '.000' AS scheduleTime -- 계획보다 12시간 넘게 이른 예측 · 실제 시각은 자정을 넘긴 다음 날로 본다 (FS001 조각과 같은 규칙) , TO_CHAR(TO_DATE(A.DEP_ARR_YMD, 'YYYY-MM-DD') + (A.FS_PREDC_MIN + CASE WHEN A.FS_PREDC_MIN < A.FS_SCHD_MIN - 720 THEN 1440 ELSE 0 END) / 1440, 'YYYY-MM-DD"T"HH24:MI":00.000"') AS estimatedTime , TO_CHAR(TO_DATE(A.DEP_ARR_YMD, 'YYYY-MM-DD') + (A.FS_ACTL_MIN + CASE WHEN A.FS_ACTL_MIN < A.FS_SCHD_MIN - 720 THEN 1440 ELSE 0 END) / 1440, 'YYYY-MM-DD"T"HH24:MI":00.000"') AS actualTime , A.ARR_DEP_ARPT_CD AS airportCode , A.ACST_NO AS standNumber , CASE WHEN TRIM(A.GATE_NO) IS NOT NULL THEN A.GATE_NO ELSE REPLACE(REPLACE(A.ACST_NO, 'L', ''), 'R', '') END AS gate , A.GATE_TYPE AS contactRemote , A.ARCFT_STGCP AS seats , A.BDPSG_CNT AS paxCount , A.TRNS_BDPSG_CNT AS transferPax , A.CRSL_NO AS belt , A.ARCFT_SUBTYPE_CD AS aircraftType , A.CKNCT_RANGE_CN AS checkInRange , A.SLF_CHKN_PSBLTY_YN AS sbdAvailable , CASE WHEN IRR_FLT_YN IN ('0', 'N') THEN 'Schedule' WHEN IRR_FLT_YN IN ('1', 'Y') THEN 'Charter' ELSE '' END AS flightType , 'N' AS triangle , A.BUS_NEED_YN AS bus , A.WAYO_ID AS arrivalGate , CASE WHEN A.FRST_BAG_INPUT_DT IS NULL OR A.FRST_BAG_INPUT_DT = '' THEN NULL ELSE TO_CHAR(A.FRST_BAG_INPUT_DT, 'YYYY-MM-DD"T"HH24:MI":00.000"') END AS baggageT1 -- 최초수하물투입일시(RS의 운항편자원 정보) , CASE WHEN A.LAST_BAG_INPUT_DT IS NULL OR A.LAST_BAG_INPUT_DT = '' THEN NULL ELSE TO_CHAR(A.LAST_BAG_INPUT_DT, 'YYYY-MM-DD"T"HH24:MI":00.000"') END AS baggageT2 -- 최종수하물투입일시(RS의 운항편자원 정보) FROM ( SELECT A.* , TO_NUMBER(SUBSTR(TRIM(A.DEP_ARR_HM), 1, 2)) * 60 + TO_NUMBER(SUBSTR(TRIM(A.DEP_ARR_HM), 3, 2)) AS FS_SCHD_MIN , TO_NUMBER(SUBSTR(TRIM(A.PREDC_HM), 1, 2)) * 60 + TO_NUMBER(SUBSTR(TRIM(A.PREDC_HM), 3, 2)) AS FS_PREDC_MIN , TO_NUMBER(SUBSTR(TRIM(A.ACTL_HM), 1, 2)) * 60 + TO_NUMBER(SUBSTR(TRIM(A.ACTL_HM), 3, 2)) AS FS_ACTL_MIN FROM PMOWN.TN_PM_SMLT_SCHDL_ATRB A WHERE A.SCHDL_ATRB_GROUP_ID = #{rsrcNo} ) A ) X ORDER BY X.domStatus, X.flightDirection, X.depArrTerminal, X.flightNumber, X.flightNumberID

/* CastApiMapper.retrieveCounterAllocation(CastReqGetResourceDto dto) */ SELECT C.blockID -- BlockID , C.depArrTerminal -- 터미널아이디 , C.resourceID -- 체크인카운터번호 , C.airlineCode -- 항공사코드 , C.domStatus -- 국내국제구분코드 , C.t1 -- 체크인오픈예정시분 , C.t2 -- 체크인클로즈예정시분 , REPLACE(C.travelClass, ' ', '') AS travelClass -- 체크인등급코드 , REPLACE(C.groupStatus, ' ', '') AS groupStatus -- 체크인그룹코드 , REPLACE(C.checkinType, ' ', '') AS checkinType -- 체크인종류코드 , REPLACE(C.nonFunctionalStatus, ' ', '') AS nonFunctionalStatus -- 체크인기능코드 , C.checkinAllocType -- 체크인유형코드 , C.checkInAllocDescryption -- 체크인유형상세정보 , TO_CHAR(SYSDATE, 'YYYY-MM-DD"T"HH24:MI:SS') AS lastModified FROM (
SELECT CASE WHEN Y.TMNL_ID = 'P03' THEN 'P03CKIN' ELSE CASE WHEN Y.DOM_INTL_SE_CD = 'I' THEN 'P01CKINInt' ELSE 'P01CKINDom' END END AS blockID , Y.TMNL_ID AS depArrTerminal , Y.CKNCT_ID AS resourceID , Y.ALN_CD AS airlineCode , CASE WHEN Y.DOM_INTL_SE_CD = 'I' THEN 'Int' ELSE 'Dom' END AS domStatus , TO_CHAR(Y.BGN_DT, 'YYYY-MM-DD"T"HH24:MI":00"') AS t1 , TO_CHAR(Y.END_DT, 'YYYY-MM-DD"T"HH24:MI":00"') AS t2 , ' ' AS travelClass , ' ' AS groupStatus , ' ' AS checkinType , ' ' AS nonFunctionalStatus , Y.CHKN_TYPE_CD AS checkinAllocType , '"' || Y.ALN_CD || '"' AS checkInAllocDescryption FROM () Y
SELECT CASE WHEN Y.TMNL_ID = 'P03' THEN 'P03CKIN' ELSE CASE WHEN Y.DOM_INTL_SE_CD = 'I' THEN 'P01CKINInt' ELSE 'P01CKINDom' END END AS blockID , Y.TMNL_ID AS depArrTerminal , Y.CKNCT_ID AS resourceID , Y.ALN_CD AS airlineCode , CASE WHEN Y.DOM_INTL_SE_CD = 'I' THEN 'Int' ELSE 'Dom' END AS domStatus , TO_CHAR(TO_DATE(Y.STA_DT, 'YYYYMMDDHH24MI'), 'YYYY-MM-DD"T"HH24:MI":00"') AS t1 , TO_CHAR(TO_DATE( CASE WHEN Y.RON_YN = 'N' THEN Y.CRTR_YMD ELSE TO_CHAR(TO_DATE(Y.CRTR_YMD, 'YYYYMMDD') + 1, 'YYYYMMDD') END || SUBSTR(Y.END_DT, 9, 4), 'YYYYMMDDHH24MI' ), 'YYYY-MM-DD"T"HH24:MI":00"') AS t2 , Y.TRVL_CLSS AS travelClass , Y.GRP_STAT AS groupStatus , Y.CIC_TYPE AS checkinType , Y.NONFUNC_STAT AS nonFunctionalStatus , Y.CHKN_TYPE_CD AS checkinAllocType , Y.CHKN_TYPE_DTL_INFO AS checkInAllocDescryption FROM (SELECT A.TMNL_ID , A.CKNCT_ID , A.ALN_CD , A.DOM_INTL_SE_CD , A.CRTR_YMD , A.CHKN_OPEN_PRNMNT_DT AS STA_DT , A.CHKN_CLOSE_PRNMNT_DT AS END_DT , CASE WHEN TO_NUMBER(A.CHKN_OPEN_PRNMNT_DT) <= TO_NUMBER(A.CHKN_CLOSE_PRNMNT_DT) THEN 'N' ELSE 'Y' END AS RON_YN , NVL(A.CHKN_GRD_CD,' ') AS TRVL_CLSS , NVL(A.CHKN_GROUP_CD,' ') AS GRP_STAT , NVL(A.CHKN_KND_CD,' ') AS CIC_TYPE , NVL(A.CHKN_FWK_CD,' ') AS NONFUNC_STAT , A.CHKN_TYPE_CD , '"' || A.CHKN_TYPE_DTL_INFO || '"' AS CHKN_TYPE_DTL_INFO FROM PMOWN.TN_PM_SMLT_CKNCT_ATRB A WHERE A.SCHDL_ATRB_GROUP_ID = #{rsrcNo}) Y
UNION ALL
) C ORDER BY CASE WHEN C.blockID LIKE '%TransferCKIN' THEN 1 ELSE 0 END , C.depArrTerminal, C.resourceID, C.t1, C.t2, C.airlineCode, C.checkInAllocDescryption

/* CastApiMapper.retrieveSelfCheckInCountAndBagDrop(CastReqGetResourceDto dto) */ SELECT K.BlockID -- BlockID , K.resourceID -- 체크인카운터번호 , K.DepArrTerminal -- 터미널아이디 , K.AirlineCode -- 항공사코드 , K.DomStatus -- 국내국제구분코드 , K.t1 -- 체크인오픈예정시분 , K.t2 -- 체크인클로즈예정시분 , REPLACE(K.TravelClass, ' ', '') AS TravelClass -- 체크인등급코드 , REPLACE(K.GroupStatus, ' ', '') AS GroupStatus -- 체크인그룹코드 , REPLACE(K.CheckinType, ' ', '') AS CheckinType -- 체크인종류코드 , REPLACE(K.NonFunctionalStatus, ' ', '') AS NonFunctionalStatus -- 체크인기능코드 , REPLACE(K.CheckinAllocType, ' ', '') AS CheckinAllocType -- 체크인유형코드 , REPLACE(K.CheckInAllocDescryption, ' ', '') AS CheckInAllocDescryption -- 체크인유형상세정보 , TO_CHAR(SYSDATE, 'YYYY-MM-DD"T"HH24:MI:SS') AS lastModified FROM (
SELECT CASE WHEN PLCY.TMNL_ID = 'P03' THEN 'P03Self' ELSE 'P01Self' END AS BlockID , PLCY.TMNL_ID AS DepArrTerminal , PLCY.SLF_CHKN_ISTR_ID AS resourceID , '"' || LISTAGG(PLCY.ALN_CD, ',') WITHIN GROUP (ORDER BY PLCY.ALN_CD) || '"' AS AirlineCode , 'Int' AS DomStatus , TO_CHAR(TO_DATE(#{baseYmd}, 'YYYYMMDD') - 1, 'YYYY-MM-DD') || 'T12:00:00.000' AS t1 , TO_CHAR(TO_DATE(#{baseYmd}, 'YYYYMMDD'), 'YYYY-MM-DD') || 'T23:59:59.000' AS t2 , '' AS TravelClass -- 체크인등급코드 , '' AS GroupStatus -- 체크인그룹코드 , '' AS CheckinType -- 체크인종류코드 , '' AS NonFunctionalStatus -- 체크인기능코드 , 'C' AS CheckinAllocType -- 체크인유형코드 , '"' || LISTAGG(PLCY.ALN_CD, ',') WITHIN GROUP (ORDER BY PLCY.ALN_CD) || '"' AS CheckInAllocDescryption -- 체크인유형상세정보 FROM PMOWN.TN_PM_SLF_CHKN_OPER_PLCY PLCY WHERE #{baseYmd} BETWEEN PLCY.PLCY_BGNG_YMD AND PLCY.PLCY_END_YMD GROUP BY PLCY.TMNL_ID, PLCY.SLF_CHKN_ISTR_ID
UNION ALL SELECT BlockID , DepArrTerminal , resourceID , '"' ||(SELECT LISTAGG(ALN, ',') WITHIN GROUP (ORDER BY ALN) FROM (SELECT DISTINCT REGEXP_SUBSTR(SBD.AirlineCode, '[^,]+', 1,LEVEL) AS ALN FROM DUAL CONNECT BY REGEXP_SUBSTR(SBD.AirlineCode, '[^,]+', 1 , LEVEL) IS NOT NULL)) || '"' AS AirlineCode -- 항공사코드 , DomStatus , t1 , t2 , '' AS TravelClass -- 체크인등급코드 , '' AS GroupStatus -- 체크인그룹코드 , '' AS CheckinType -- 체크인종류코드 , '' AS NonFunctionalStatus -- 체크인기능코드 , 'C' AS CheckinAllocType -- 체크인유형코드 , '"' ||(SELECT LISTAGG(ALN, ',') WITHIN GROUP (ORDER BY ALN) FROM (SELECT DISTINCT REGEXP_SUBSTR(SBD.AirlineCode, '[^,]+', 1,LEVEL) AS ALN FROM DUAL CONNECT BY REGEXP_SUBSTR(SBD.AirlineCode, '[^,]+', 1 , LEVEL) IS NOT NULL)) || '"' AS CheckInAllocDescryption -- 체크인유형상세정보 FROM ( SELECT CASE WHEN CIC.TMNL_ID = 'P03' THEN 'P03SBD' ELSE 'P01SBD' END AS BlockID -- BlockID , CIC.TMNL_ID AS DepArrTerminal -- 터미널아이디 , CIC.CKNCT_ID AS resourceID -- 체크인카운터번호 , S.ALN_CD_LIST AS AirlineCode -- 항공사코드 , CASE WHEN CIC.DOM_INTL_SE_CD = 'I' THEN 'Int' ELSE 'Dom' END AS DomStatus -- 국내국제구분코드 , TO_CHAR(TO_DATE(S.OPEN_TM, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD"T"HH24:MI:SS".000"') AS t1 , TO_CHAR(TO_DATE(S.CLOSE_TM, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD"T"HH24:MI:SS".000"') AS t2 FROM CAOWN.TN_CA_CKNCT CIC INNER JOIN () S ON S.TMNL_ID = CIC.TMNL_ID AND S.CHKN_ISL_CD = SUBSTR(CIC.CKNCT_ID, 1, 1) WHERE CIC.USE_YN = 'Y' AND CIC.CKNCT_USE_CRG_APLCN_TYPE_CD = 'H' ) SBD
SELECT Y.BLCK_ID AS BlockID , Y.TMNL_ID AS DepArrTerminal , Y.CKNCT_ID AS resourceID , '"' || Y.CHKN_TYPE_DTL_INFO || '"' AS AirlineCode , CASE WHEN Y.DOM_INTL_SE_CD = 'I' THEN 'Int' ELSE 'Dom' END AS DomStatus -- 국내국제구분코드 , TO_CHAR(TO_DATE(Y.STA_DT, 'YYYYMMDDHH24MI'), 'YYYY-MM-DD"T"HH24:MI":00"') AS t1 , TO_CHAR(TO_DATE( CASE WHEN Y.RON_YN = 'N' THEN Y.OPR_DT ELSE TO_CHAR(TO_DATE(Y.OPR_DT, 'YYYYMMDD') + 1, 'YYYYMMDD') END || SUBSTR(Y.END_DT,9,4), 'YYYYMMDDHH24MI' ), 'YYYY-MM-DD"T"HH24:MI":00"') AS t2 , Y.TRVL_CLSS AS TravelClass , Y.GRP_STAT AS GroupStatus , Y.CIC_TYPE AS CheckinType , Y.NONFUNC_STAT AS NonFunctionalStatus , Y.CHKN_TYPE_CD AS CheckinAllocType , '"' || Y.CHKN_TYPE_DTL_INFO || '"' AS CheckInAllocDescryption FROM (SELECT A.BLCK_ID , A.TMNL_ID , A.CKNCT_ID , A.ALN_CD , A.DOM_INTL_SE_CD , A.CRTR_YMD AS OPR_DT , A.OPER_BGNG_DT AS STA_DT , A.OPER_END_DT AS END_DT , CASE WHEN TO_NUMBER(A.OPER_BGNG_DT) <= TO_NUMBER(A.OPER_END_DT) THEN 'N' ELSE 'Y' END AS RON_YN , NVL(A.CHKN_GRD_CD,' ') AS TRVL_CLSS , NVL(A.CHKN_GROUP_CD,' ') AS GRP_STAT , NVL(A.CHKN_KND_CD,' ') AS CIC_TYPE , NVL(A.CHKN_FWK_CD,' ') AS NONFUNC_STAT , NVL(A.CHKN_TYPE_CD,' ') AS CHKN_TYPE_CD , NVL(A.CHKN_TYPE_DTL_INFO,' ') AS CHKN_TYPE_DTL_INFO FROM PMOWN.TN_PM_SMLT_SBD_ATRB A WHERE A.SCHDL_ATRB_GROUP_ID = #{rsrcNo}) Y
) K ORDER BY K.DepArrTerminal, K.resourceID, K.t1, K.t2, K.BlockID, K.AirlineCode

    /* CastApiMapper.retrieveNewCastModelId(CastModelDto dto) */
SELECT NVL(MAX(TO_NUMBER(SMLT_MDL_SN)),0)+1 AS smltMdlSn
  FROM PMOWN.TN_PM_SMLT_MDL

mapper.insert:
/* CastApiMapper.insertCASTModel(SmltMdlDto dto) */
INSERT INTO PMOWN.TN_PM_SMLT_MDL
(
    SMLT_MDL_SN
    , SMLT_MDL_EXPLN
    , SMLT_MDL_FILE_PATH_NM
    , DEL_YN
    , SMLT_MDL_TYPE_CD
    , FRST_RGTR_ID
    , FRST_RGTR_IP_ADDR
    , FRST_REG_DT
) VALUES (
    #{smltMdlSn}
    , #{smltMdlExpln}
    , #{smltMdlFilePathNm}
    , 'N'
    , #{smltMdlTypeCd}
    , 'system'
    , #{loginIpAddr}
    , CURRENT_TIMESTAMP
)

mapper.update:
 /* CastApiMapper.updateCASTModel(CastModelDto dto) */
UPDATE PMOWN.TN_PM_SMLT_MDL SET
       LAST_MDFR_ID = 'SYSTEM'
    , LAST_MDFR_IP_ADDR = #{loginIpAddr}
    , LAST_MDFCN_DT = CURRENT_TIMESTAMP
 WHERE SMLT_MDL_EXPLN = #{resourceID}

mapper.select:
    /* CastApiMapper.retrieveModelInfo(CastModelDto dto) */
SELECT SMLT_MDL_SN AS smltMdlSn
    , SMLT_MDL_TYPE_CD AS smltMdlTypeCd
    , SMLT_EXCN_SE_CD smltExcnSeCd
  FROM PMOWN.TN_PM_SMLT_MDL
  WHERE SMLT_MDL_EXPLN = #{modelResourceID}

/* CastApiMapper.retrieveFcltyOpngTblTrnstScrtyCntrl(CastReqGetResourceDto dto) */
WITH DPL AS () SELECT A.TMNL_ID AS terminal , CASE WHEN A.FCLTY_TYPE_ID = 'W' THEN 'West' WHEN A.FCLTY_TYPE_ID = 'E' THEN 'East' ELSE '' END AS location , REPLACE(CASE WHEN B.OPER_BGNG_1_HR IS NOT NULL THEN TO_CHAR(TO_DATE(B.BGNG_YMD, 'YYYY-MM-DD'), 'YYYY-MM-DD') || 'T00:00:00.000' ELSE '1900-01-01T00:00:00.000' END, ' ', '') AS startDate , REPLACE(CASE WHEN B.OPER_BGNG_1_HR IS NOT NULL THEN '1899-12-30T' || TO_CHAR(TO_DATE(B.OPER_BGNG_1_HR || '00', 'HH24:MI:SS'),'HH24:MI:SS') || '.000' ELSE '1899-12-30T00:00:00.000' END, ' ', '') AS startTime , REPLACE(CASE WHEN B.OPER_END_1_HR IS NOT NULL THEN TO_CHAR(TO_DATE(NVL(B.END_YMD,'21001231'), 'YYYY-MM-DD'), 'YYYY-MM-DD') || 'T00:00:00.000' ELSE '2100-12-31T00:00:00.000' END, ' ', '') AS endDate , REPLACE(CASE WHEN B.OPER_END_1_HR IS NOT NULL THEN '1899-12-30T' || TO_CHAR(TO_DATE(B.OPER_END_1_HR || '00', 'HH24:MI:SS'),'HH24:MI:SS') || '.000' ELSE '1899-12-30T23:59:00.000' END, ' ', '') AS endTime , TO_CHAR(A.FCLTY_CNT) AS currentNumberofLanes , (SELECT TO_CHAR(NVL(M.LAST_MDFCN_DT, M.FRST_REG_DT), 'YYYY-MM-DD"T"HH24:MI:SS') FROM PMOWN.TN_PM_SMLT_FCLTY_OPNG_TRNST_SCRTY_CNTRL_MSTR M WHERE M.USE_YN = 'Y' AND M.TRNST_SCRTY_CNTRL_ATRB_ID = #{rsrcNo}) AS lastModified FROM PMOWN.TN_PM_SMLT_FCLTY_OPNG_TRNST_SCRTY_CNTRL_ATRB A INNER JOIN ( SELECT TMNL_ID, FCLT_SE_CD, FCLTY_TYPE_ID, PRD_SN, ELMNT_SN, BGNG_YMD, END_YMD, OPER_BGNG_1_HR, OPER_END_1_HR FROM DPL UNION ALL
SELECT 'P02', FCLT_SE_CD, FCLTY_TYPE_ID, PRD_SN, ELMNT_SN, BGNG_YMD, END_YMD, OPER_BGNG_1_HR, OPER_END_1_HR FROM DPL WHERE TMNL_ID = 'P01' ) B ON A.TMNL_ID = B.TMNL_ID AND A.FCLT_SE_CD = B.FCLT_SE_CD AND A.FCLTY_TYPE_ID = B.FCLTY_TYPE_ID WHERE A.TRNST_SCRTY_CNTRL_ATRB_ID = #{rsrcNo}
AND NVL(B.OPER_BGNG_1_HR, '0000') != NVL(B.OPER_END_1_HR, '2359') ORDER BY A.TMNL_ID, A.FCLT_SE_CD, A.FCLTY_TYPE_ID, B.PRD_SN, B.ELMNT_SN

mapper.insert:
    /* CastApiMapper.insertSimSet(CastResReqDto dto) */
INSERT INTO PMOWN.TN_PM_SMLT_STNG
         (  SMLT_ID
          , SMLT_MDL_SN
          , SMLT_NM
          , SMLT_TYPE
          , CRTR_DT
          , EXCN_YMD
          , TMNL_ID
          , SLF_ID
          , PRNT_ID
          , FLT_SCHDL_RSRC_ID
          , BAG_ALCTN_RSRC_ID
          , CKNCT_ALCTN_RSRC_ID
          , PRPT_SET_RSRC_ID
          , MDL_RSRC_ID
          , EXCN_ID
          , CKNCT_SRVC_HR_RSRC_ID
          , CHKN_TYPE_RSRC_ID
          , FCLTY_OPNG_DPTCNY_SRNG_RSRC_ID
          , FCLTY_OPNG_EMI_RSRC_ID
          , FCLTY_OPNG_IMMI_RSRC_ID
          , FCLTY_OPNG_SCRTY_CNTRL_RSRC_ID
          , FCLTY_OPNG_TR_SCRTY_CNTRL_RSRC_ID
          , SBD_CNTRL_ALCTN_ID
          , PLAN_BGNG_DT
          , PLAN_END_DT
          , SMLT_BGNG_DT
          , SMLT_END_DT
          , BDPSG_ANCE_YN
          , FRST_RGTR_ID
          , FRST_RGTR_IP_ADDR
          , FRST_REG_DT)
VALUES (    #{simId}
          , #{smltMdlSn}
          , #{resourceID}
          , #{smltType}
          , CURRENT_TIMESTAMP
          -- 사용자 실행은 요청의 대상일. 일일은 resolveBaseYmd() 의 기준일자
          , NVL(#{excnYmd}, substr(replace(replace(#{startTime},'T',' '),'-',''),1,8))
          -- 사용자 실행이면 요청의 터미널을 따른다. 일일은 예전대로 P01
          , NVL(#{tmnlId}, 'P01')
          , #{selfID}
          , #{parentID}
          , #{flightScheduleResourceID}
          , #{bagAllocationResourceID}
          , #{checkInAllocationResourceID}
          , #{propertySetResourceID}
          , #{modelResourceID}
          , #{runID}
