mapper.update:
/* CastApiMapper.updateWhatIfDefinitionTable(CastWhatIfCntrlDto dto) */
UPDATE PMOWN.TN_PM_SMLT_USER_MSTR
SET    SMLT_STTS = #{status}
     , EXCT_DT = CASE
                   WHEN #{status} = 'Executing' THEN CURRENT_TIMESTAMP
                    ELSE EXCT_DT
                 END
     , END_DT = CASE
                   WHEN #{status} IN ('Finished', 'Failed', 'Cancelled') THEN CURRENT_TIMESTAMP
                   ELSE END_DT
                END
     , LAST_MDFR_ID = 'SYSTEM'
     , LAST_MDFR_IP_ADDR = #{loginIpAddr}
     , LAST_MDFCN_DT = CURRENT_TIMESTAMP
WHERE SMLT_REQ_ID = #{whatIfRunId}
AND SMLT_STTS = #{fromStatus}

mapper.select:
/* CastApiMapper.retrieveUserReqByFsRsrcId(String fltSchdlRsrcId) */
SELECT *
FROM PMOWN.TN_PM_SMLT_USER_MSTR
WHERE FLT_SCHDL_RSRC_ID = #{fltSchdlRsrcId}

