/* CastApiMapper.updateUserReqFinished(UserSmltReqDto dto) */
UPDATE PMOWN.TN_PM_SMLT_USER_MSTR
SET    SMLT_STTS = 'Finished'
     , END_DT = CURRENT_TIMESTAMP
     , LAST_MDFR_ID = 'CAST'
     , LAST_MDFR_IP_ADDR = #{loginIpAddr}
     , LAST_MDFCN_DT = CURRENT_TIMESTAMP
WHERE SMLT_REQ_ID = #{smltReqId}
AND SMLT_STTS IN ('New', 'Executing', 'Finished')
